// Verifica que el mensaje viene de THERS y no es una repetición. NADA se envía si algo falla.
// El cuerpo se firma EXACTO (bytes), por eso el Webhook guarda el cuerpo crudo (rawBody).
const crypto = require('crypto');

const secret = $env.N8N_WEBHOOK_SECRET || '';
const headers = $input.first().json.headers || {};
const timestamp = headers['x-thers-timestamp'];
const signature = headers['x-thers-signature'] || '';
const idempotencyKey = headers['x-thers-idempotency-key'] || '';
const fail = (reason) => [{ json: { valid: false, reason } }];

if (!secret) return fail('sin secreto configurado');

const raw = await this.helpers.getBinaryDataBuffer(0, 'data');

// 1) Marca de tiempo reciente (5 minutos): una captura no se puede repetir pasado ese rato.
const now = Math.floor(Date.now() / 1000);
const ts = Number.parseInt(timestamp, 10);
if (!Number.isFinite(ts) || Math.abs(now - ts) > 300) return fail('marca de tiempo');

// 2) Firma HMAC-SHA256 de "<marca>.<cuerpo>", comparada en tiempo constante.
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(ts + '.').update(raw).digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(signature);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return fail('firma');

// 3) Idempotencia: la misma clave no se procesa dos veces (los reintentos de THERS son seguros).
//    Se marca ANTES de enviar: es "como máximo una vez"; perder un correo es mejor que mandar dos.
const seen = $getWorkflowStaticData('global');
seen.keys = seen.keys || [];
if (seen.keys.includes(idempotencyKey)) return [{ json: { valid: true, duplicate: true } }];
seen.keys.push(idempotencyKey);
if (seen.keys.length > 500) seen.keys.shift();

return [{ json: { valid: true, duplicate: false, payload: JSON.parse(raw.toString('utf8')) } }];

// Redacta el correo. Es GENÉRICO a propósito: no dice qué se hizo, a quién ni por qué
// (ADR-032: la nota de quien modera y la identidad de la otra cuenta no se cuentan).
const { payload } = $('Verificar firma').first().json;

const texts = {
  es: {
    subject: 'Revisamos tu reporte',
    actioned: 'Gracias por avisarnos. Revisamos tu reporte y tomamos medidas. Por seguridad no damos más detalles sobre otras cuentas. Si ves algo más, puedes volver a reportarlo desde la app.',
    dismissed: 'Gracias por avisarnos. Revisamos tu reporte y, con la información disponible, no encontramos una infracción de nuestras normas. Si crees que nos falta contexto, puedes volver a reportarlo con más detalle desde la app.',
  },
  en: {
    subject: 'We reviewed your report',
    actioned: 'Thanks for letting us know. We reviewed your report and took action. For safety we do not share details about other accounts. If you see anything else, you can report it again from the app.',
    dismissed: 'Thanks for letting us know. We reviewed your report and, with the information available, did not find a violation of our rules. If you think we are missing context, you can report it again with more detail from the app.',
  },
};
const t = texts[payload.language] || texts.es;
const body = t[payload.outcome];
if (!body) throw new Error('desenlace desconocido');

return [{ json: { to: payload.recipient_email, subject: t.subject, text: body + '\n\n— THERS' } }];
